import{_ as t,o as a,c as d,a1 as o}from"./chunks/framework.DceXOx8u.js";const p=JSON.parse('{"title":"Ejemplos","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/es/ejemplos/"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/es/ejemplos/"}]]},"headers":[],"relativePath":"es/ejemplos/index.md","filePath":"es/ejemplos/index.md"}'),r={name:"es/ejemplos/index.md"};function i(s,e,n,c,l,u){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="ejemplos" tabindex="-1">Ejemplos <a class="header-anchor" href="#ejemplos" aria-label="Permalink to &quot;Ejemplos&quot;">​</a></h1><p>Bots completos para copiar, ejecutar y adaptar. Casi todos los ejemplos son un único archivo <code>bot.js</code> que muestra un conjunto de funciones de botmesh, con una transcripción capturada de una ejecución real y enlaces a la guía de cada función que usa. Un test ejecuta el código de cada ejemplo y comprueba su transcripción, así que lo que lees es lo que obtienes.</p><h2 id="ejecutar-cualquier-ejemplo" tabindex="-1">Ejecutar cualquier ejemplo <a class="header-anchor" href="#ejecutar-cualquier-ejemplo" aria-label="Permalink to &quot;Ejecutar cualquier ejemplo&quot;">​</a></h2><ol><li><p>Prepara un proyecto una vez, como en <a href="/botmesh/es/guide/inicio#requisitos">Inicio rápido</a> (Node.js 22.12+, <code>&quot;type&quot;: &quot;module&quot;</code>, <code>npm install @botmesh/core @botmesh/baileys</code>).</p></li><li><p>Guarda el código del ejemplo como <code>bot.js</code>.</p></li><li><p>Chatea con él en la terminal, sin teléfono:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> botmesh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bot.js</span></span></code></pre></div></li><li><p>Conéctalo de verdad con <code>node bot.js</code> (un QR para WhatsApp), o cambia el provider para <a href="/botmesh/es/guide/inicio#o-conectar-telegram">Telegram</a>. El código del bot no cambia entre canales.</p></li></ol><h2 id="principiante" tabindex="-1">Principiante <a class="header-anchor" href="#principiante" aria-label="Permalink to &quot;Principiante&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ejemplo</th><th>Nivel</th><th>Etiquetas</th><th>Funciones</th><th>Qué vas a construir</th></tr></thead><tbody><tr><td><a href="./bot-saludo">Bot de saludo</a></td><td>Principiante</td><td>Comandos</td><td><code>WELCOME</code>, triggers de texto y regex, <code>ctx.pass()</code>, comandos slash, catch-all</td><td>Un bot que da la bienvenida una vez, saluda, repite y lista sus comandos</td></tr><tr><td><a href="./bot-faq">Bot de FAQ</a></td><td>Principiante</td><td>Triggers</td><td>Coincidencia normalizada, listas, <code>contains</code>, regex, precedencia</td><td>Respuestas por palabra clave a preguntas frecuentes, con fallback</td></tr><tr><td><a href="./mensajes">Enviar mensajes</a></td><td>Principiante</td><td>Triggers</td><td>Formas de trigger, <code>ctx.quote()</code>, <code>ctx.react()</code>, datos del remitente</td><td>Todas las formas de responder a un texto</td></tr><tr><td><a href="./bot-menu">Bot de menú</a></td><td>Principiante</td><td>Flujos, Botones</td><td><code>flow().choose()</code>, sub-flujos <code>then</code>, <code>bot.conversation()</code>, botones por canal</td><td>El menú de una pizzería que funciona en todos los canales</td></tr><tr><td><a href="./bot-encuesta">Bot de encuestas</a></td><td>Principiante</td><td>Encuestas, Reacciones</td><td><code>ctx.poll()</code>, <code>bot.on(&#39;poll&#39;)</code>, <code>bot.send()</code>, <code>ctx.react()</code></td><td>Encuestas nativas respondidas con el recuento en vivo</td></tr><tr><td><a href="./media">Respuestas con media</a></td><td>Principiante</td><td>Media</td><td>Foto, archivo, video, voz, sticker, ubicación, contacto; <code>bot.onType()</code>, <code>loadMediaOf()</code></td><td>Un bot que envía cada tipo de media y reacciona a imágenes</td></tr><tr><td><a href="./recordatorios">Bot de recordatorios</a></td><td>Principiante</td><td>Scheduler</td><td><code>bot.delay()</code>, <code>bot.schedule()</code> con zona horaria, <code>task.cancel()</code>, <code>bot.send()</code></td><td>Recordatorios puntuales y un consejo diario a las 9:00</td></tr><tr><td><a href="./flujo-registro">Flujo de registro</a></td><td>Principiante</td><td>Flujos, Formularios</td><td><code>.ask()</code> con <code>validate</code>, <code>.do()</code>, <code>c.state</code>, <code>.timeout()</code>, <code>/cancel</code></td><td>Un alta validada que guarda al usuario</td></tr></tbody></table><h2 id="intermedio" tabindex="-1">Intermedio <a class="header-anchor" href="#intermedio" aria-label="Permalink to &quot;Intermedio&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ejemplo</th><th>Nivel</th><th>Etiquetas</th><th>Funciones</th><th>Qué vas a construir</th></tr></thead><tbody><tr><td><a href="./flujo-compra">Flujo de compra</a></td><td>Intermedio</td><td>Flujos</td><td><code>.choose()</code>, sub-flujos <code>then</code>, <code>goto</code>, estado calculado, timeouts</td><td>Una tienda pequeña con cantidad, confirmación y dirección</td></tr><tr><td><a href="./flujo-soporte">Soporte con timeout</a></td><td>Intermedio</td><td>Conversaciones</td><td><code>bot.conversation()</code>, <code>c.waitText()</code>, <code>c.choose()</code>, <code>ConversationTimeout</code>, <code>ConversationCancelled</code></td><td>Un servicio de soporte que abre tickets y maneja sesiones abandonadas</td></tr><tr><td><a href="./rate-limiter">Plugin: rate limiter</a></td><td>Intermedio</td><td>Plugins, Hooks</td><td><code>definePlugin()</code>, <code>before(&#39;message&#39;)</code>, <code>abort()</code>, <code>onDispose()</code></td><td>Un plugin reutilizable que limita los mensajes por usuario</td></tr><tr><td><a href="./reserva-citas">Reserva de citas</a></td><td>Intermedio</td><td>WhatsApp, Formularios, SQLite</td><td><code>.persistent()</code>, <code>.form()</code>, <code>validate</code> + <code>maxAttempts</code>, <code>SQLiteStore</code>, <code>ctx.user</code></td><td>Un flujo de reservas que valida, confirma y se retoma tras un reinicio</td></tr><tr><td><a href="./seguimiento-pedidos">Seguimiento de pedidos</a></td><td>Intermedio</td><td>WhatsApp, Datos de usuario</td><td>namespaces de <code>ctx.user</code>, <code>bot.conversation()</code>, <code>MemoryStore</code> con archivo</td><td>Consultas de pedidos que recuerdan lo que sigue cada usuario</td></tr><tr><td><a href="./handoff-humano">Handoff humano</a></td><td>Intermedio</td><td>WhatsApp, Soporte</td><td><code>ctx.handoff()</code>, <code>bot.resume()</code>, eventos de handoff, comandos de agente, <code>bot.delay()</code></td><td>Un bot de soporte que pasa chats a agentes y los recupera</td></tr><tr><td><a href="./multi-idioma">Bot multi-idioma</a></td><td>Intermedio</td><td>WhatsApp, Telegram, i18n</td><td><code>bot.locale()</code>, <code>ctx.t()</code>, <code>detect</code>, <code>ctx.setLang()</code>, plurales</td><td>Un bot que responde a cada usuario en español o en inglés</td></tr><tr><td><a href="./bot-de-grupo">Bot de grupo</a></td><td>Intermedio</td><td>WhatsApp, Telegram, Grupos</td><td>conversaciones por participante, <code>scope</code>, menciones, <code>groupMode</code>, comandos solo para admins</td><td>Un quiz de grupo con marcador y comandos de administración</td></tr><tr><td><a href="./whatsapp-y-telegram">WhatsApp y Telegram a la vez</a></td><td>Intermedio</td><td>WhatsApp, Telegram, SQLite</td><td><code>defineBot</code>, dos providers, espacios de nombres del store, ids estables</td><td>Un archivo de bot que atiende dos canales desde un proceso</td></tr></tbody></table><h2 id="ia" tabindex="-1">IA <a class="header-anchor" href="#ia" aria-label="Permalink to &quot;IA&quot;">​</a></h2><p>Usan <a href="/botmesh/es/guide/ai"><code>@botmesh/ai</code></a> con Anthropic por defecto; cada página muestra cómo cambiar a OpenAI, Gemini o un modelo local de Ollama. La API key siempre sale de una variable de entorno.</p><table tabindex="0"><thead><tr><th>Ejemplo</th><th>Nivel</th><th>Etiquetas</th><th>Funcionalidades</th><th>Qué hace</th></tr></thead><tbody><tr><td><a href="./ia-faq">Asistente de preguntas frecuentes con IA</a></td><td>Principiante</td><td>IA, Límites</td><td>autoresponder, persona, triggers de función, <code>/reset</code></td><td>Responde dudas de una tienda con un LLM, rechaza lo que no es del tema y deja las respuestas fijas fuera del modelo.</td></tr><tr><td><a href="./ia-herramientas-citas">Asistente de citas con IA</a></td><td>Intermedio</td><td>IA, Herramientas</td><td>tool calling, <code>confirm: true</code>, <code>confirmLines</code>, <code>dedupe</code>, <code>enum</code></td><td>Reserva, lista y cancela citas con tus funciones, con una confirmación antes de cada cambio.</td></tr><tr><td><a href="./ia-rag">IA con tus preguntas frecuentes</a></td><td>Intermedio</td><td>IA, RAG</td><td>retriever de <code>rag</code>, <code>appendSources</code>, <code>warmup()</code></td><td>Responde a partir de un FAQ en Markdown, cita la sección que usó y admite lo que no sabe.</td></tr><tr><td><a href="./ia-streaming">Respuestas de IA en streaming</a></td><td>Intermedio</td><td>IA, Streaming, Telegram</td><td><code>stream</code>, borradores / ediciones / trozos, coste y latencia</td><td>Muestra la respuesta mientras el modelo la escribe, ajustada para coste y latencia.</td></tr><tr><td><a href="./ia-enrutador">Enrutador con IA</a></td><td>Avanzado</td><td>IA, Flujos</td><td><code>generate()</code>, <code>replyInChat()</code>, flujos, <code>bot.trigger()</code></td><td>Clasifica el texto libre con el modelo, lleva los pagos a flujos deterministas y deja la charla a la IA.</td></tr><tr><td><a href="./ia-escalado-humano">IA con escalado a humano</a></td><td>Avanzado</td><td>IA, Herramientas, Handoff</td><td>tool calling, <code>ctx.handoff()</code>, <code>bot.resume()</code>, comandos de escape</td><td>Pasa el chat a una persona con un resumen para el agente y lo recupera con <code>/bot</code>.</td></tr></tbody></table><h2 id="avanzado" tabindex="-1">Avanzado <a class="header-anchor" href="#avanzado" aria-label="Permalink to &quot;Avanzado&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ejemplo</th><th>Nivel</th><th>Etiquetas</th><th>Funcionalidades</th><th>Qué construyes</th></tr></thead><tbody><tr><td><a href="./webhook-cloud-api">Servidor de webhooks para la Cloud API</a></td><td>Avanzado</td><td>WhatsApp, Cloud API, Webhooks, Seguridad</td><td>Webhooks de <code>@botmesh/meta</code>, firmas sobre el body crudo, ventana de 24 h, plantillas</td><td>Un servidor <code>node:http</code> para la Cloud API oficial, con plantilla de respaldo</td></tr><tr><td><a href="./bot-produccion">Bot listo para producción</a></td><td>Avanzado</td><td>Producción, Docker, SQLite, Durabilidad</td><td><code>SQLiteStore</code>, durabilidad, flujos persistentes, salud y métricas, apagado ordenado, logs</td><td>Un bot de soporte empaquetado como proyecto pequeño con Dockerfile</td></tr><tr><td><a href="./resumen-diario">Resumen diario programado</a></td><td>Avanzado</td><td>Scheduler, Broadcast, Zonas horarias</td><td>Scheduler durable, zonas horarias, <code>bot.broadcast</code>, altas y bajas con <code>ctx.user</code></td><td>Un resumen a las 08:00 en la zona horaria del bot, una vez al día aunque haya reinicios</td></tr><tr><td><a href="./probar-tu-bot">Probar tu bot</a></td><td>Avanzado</td><td>Testing, Vitest, Transcripciones doradas</td><td><code>createTestBot</code>, <code>expectReply</code>, transcripciones doradas, reproducción</td><td>Un archivo de Vitest completo que graba y reproduce una conversación</td></tr><tr><td><a href="./plugin-faq">Crear un plugin: FAQ con herramientas</a></td><td>Avanzado</td><td>Plugins, Inyección de dependencias</td><td><code>definePlugin</code>, <code>install</code>/<code>uninstall</code>, <code>ctx.onDispose</code>, <code>provide</code></td><td>Un plugin de FAQ reutilizable que comparte sus contadores como herramienta</td></tr></tbody></table><h2 id="cobertura-de-funcionalidades" tabindex="-1">Cobertura de funcionalidades <a class="header-anchor" href="#cobertura-de-funcionalidades" aria-label="Permalink to &quot;Cobertura de funcionalidades&quot;">​</a></h2><p>Qué ejemplos muestran cada funcionalidad principal. Todos los ejemplos corren también en el <a href="/botmesh/es/guide/simulador">simulador de la terminal</a> y, salvo el servidor de webhooks de la Cloud API, en WhatsApp (Baileys) y Telegram con el mismo código del bot.</p><table tabindex="0"><thead><tr><th>Funcionalidad</th><th>Ejemplos</th></tr></thead><tbody><tr><td>Flujos (DSL <code>flow()</code>)</td><td><a href="./flujo-registro">Flujo de registro</a>, <a href="./bot-menu">Bot de menú</a>, <a href="./flujo-compra">Flujo de compra</a>, <a href="./reserva-citas">Reserva de citas</a>, <a href="./ia-enrutador">Enrutador con IA</a>, <a href="./probar-tu-bot">Probar tu bot</a>, <a href="./webhook-cloud-api">Webhooks de la Cloud API</a></td></tr><tr><td>Preguntas, menús y formularios (<code>ask</code>, <code>choose</code>, <code>form</code>)</td><td><a href="./flujo-registro">Flujo de registro</a>, <a href="./bot-menu">Bot de menú</a>, <a href="./flujo-compra">Flujo de compra</a>, <a href="./flujo-soporte">Soporte con timeout</a>, <a href="./reserva-citas">Reserva de citas</a>, <a href="./seguimiento-pedidos">Seguimiento de pedidos</a></td></tr><tr><td>Triggers y comandos</td><td><a href="./bot-saludo">Bot de saludo</a>, <a href="./bot-faq">Bot de FAQ</a>, <a href="./mensajes">Enviar mensajes</a>, <a href="./bot-de-grupo">Bot de grupo</a>, <a href="./plugin-faq">Plugin de FAQ</a></td></tr><tr><td>Media (enviar y recibir)</td><td><a href="./media">Respuestas con media</a></td></tr><tr><td>Encuestas</td><td><a href="./bot-encuesta">Bot de encuestas</a></td></tr><tr><td>Botones</td><td><a href="./bot-menu">Bot de menú</a>, <a href="./ia-herramientas-citas">Asistente de citas con IA</a></td></tr><tr><td>Hooks</td><td><a href="./rate-limiter">Rate limiter</a>, <a href="./multi-idioma">Bot multi-idioma</a></td></tr><tr><td>Plugins</td><td><a href="./rate-limiter">Rate limiter</a>, <a href="./plugin-faq">Plugin de FAQ</a></td></tr><tr><td>i18n</td><td><a href="./multi-idioma">Bot multi-idioma</a></td></tr><tr><td>Datos de usuario (<code>ctx.user</code>)</td><td><a href="./seguimiento-pedidos">Seguimiento de pedidos</a>, <a href="./reserva-citas">Reserva de citas</a>, <a href="./resumen-diario">Resumen diario</a>, <a href="./whatsapp-y-telegram">WhatsApp y Telegram</a></td></tr><tr><td>Handoff humano</td><td><a href="./handoff-humano">Handoff humano</a>, <a href="./ia-escalado-humano">IA con escalado a humano</a></td></tr><tr><td>Grupos</td><td><a href="./bot-de-grupo">Bot de grupo</a></td></tr><tr><td>Scheduler</td><td><a href="./recordatorios">Bot de recordatorios</a>, <a href="./resumen-diario">Resumen diario</a>, <a href="./handoff-humano">Handoff humano</a></td></tr><tr><td>Broadcast</td><td><a href="./resumen-diario">Resumen diario</a></td></tr><tr><td>Stores</td><td><a href="./reserva-citas">Reserva de citas</a>, <a href="./seguimiento-pedidos">Seguimiento de pedidos</a>, <a href="./whatsapp-y-telegram">WhatsApp y Telegram</a>, <a href="./bot-produccion">Bot listo para producción</a>, <a href="./resumen-diario">Resumen diario</a></td></tr><tr><td>Durabilidad</td><td><a href="./bot-produccion">Bot listo para producción</a></td></tr><tr><td>Multicanal (un bot, varios providers)</td><td><a href="./whatsapp-y-telegram">WhatsApp y Telegram</a></td></tr><tr><td>Webhooks y WhatsApp Cloud API</td><td><a href="./webhook-cloud-api">Webhooks de la Cloud API</a></td></tr><tr><td>Telegram</td><td><a href="./whatsapp-y-telegram">WhatsApp y Telegram</a>, <a href="./ia-streaming">IA en streaming</a>, <a href="./bot-de-grupo">Bot de grupo</a>, <a href="./multi-idioma">Bot multi-idioma</a></td></tr><tr><td>Chat con IA</td><td><a href="./ia-faq">Asistente de FAQ con IA</a>, <a href="./ia-rag">IA con tus preguntas frecuentes</a>, <a href="./ia-enrutador">Enrutador con IA</a></td></tr><tr><td>Herramientas de IA con confirmación</td><td><a href="./ia-herramientas-citas">Asistente de citas con IA</a>, <a href="./ia-escalado-humano">IA con escalado a humano</a></td></tr><tr><td>Historial de IA y RAG</td><td><a href="./ia-rag">IA con tus preguntas frecuentes</a>, <a href="./ia-faq">Asistente de FAQ con IA</a>, <a href="./ia-enrutador">Enrutador con IA</a></td></tr><tr><td>Streaming de IA</td><td><a href="./ia-streaming">IA en streaming</a></td></tr><tr><td>Testing</td><td><a href="./probar-tu-bot">Probar tu bot</a>, <a href="./ia-streaming">IA en streaming</a></td></tr><tr><td>Simulador en la terminal (<code>npx botmesh dev</code>)</td><td><a href="./bot-saludo">Bot de saludo</a>, <a href="./bot-encuesta">Bot de encuestas</a>, <a href="./probar-tu-bot">Probar tu bot</a></td></tr></tbody></table><p>Salvo el servidor de webhooks de la Cloud API, el código de cada ejemplo es el mismo en WhatsApp (Baileys) y Telegram: solo cambia el provider. Cuando un canal muestra algo distinto (botones, stickers), la página del ejemplo lo dice, y la <a href="/botmesh/es/guide/canales#matriz-de-capacidades">matriz de capacidades</a> da los detalles.</p>',17)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
